FACTS['0019']['sch'][0]=('外國學生入學／學位生獎學金','新生一次性部分學雜費補助，官網約20–50%，依核定；在校生一年一次5,000–20,000元，不是每月津貼。',FACTS['0019']['sch'][0][2],'0019_s')
FACTS['0020']['sch']=[('東華外國學生獎學金－在校生','一學期部分至全額學費減免；獲生活津貼者每學期20,000–40,000元，期間5個月，需審查。','至少完成一學期全日制修業、完成註冊繳費、無處分，不得兼領臺灣政府獎學金。學士最長8學期、碩士4學期、博士6學期；博士延長另審、僅半額減免。中文授課須TOCFL Level 3或華語課證明；英語授課須兩門華語課或Level 1等證明。115-1在校生公告，新生核獎內容另待確認。','0020_s3')]
FACTS['0024']['sch']=[('外國學生就學獎助學金','學士通常第二年起可減免學雜費或住宿費；一年級需特殊情形或表現經專案審議。碩博可減免學雜費、每學期最多15學分費及宿舍費，依核定。每月生活金額依當年簡章，未確認不填數字。','111年5月5日版現行官網辦法：新生隨入學申請；每年續申請，學士成績75分、碩博80分、操行80分。碩士原則2年、博士3年，可另審最多1年延長；不得領其他獎學金，須服務回饋。','0024_p2')]
FACTS['0033'].update(b='0033_b',year='115-1',fee=1000,feeNote='每位學生NT$1,000或US$40，最多3系；匯款手續費另付，申請費不退。')
FACTS['0033']['sch']=[('外國學生就學獎助金','可學費／研究生學分費減免、每月津貼或教學研究助理補助；金額由委員會依成績及預算核定，官網未列固定保證金額。','新生隨入學申請，每次核定一學年。續領操行80分且無處分，學費減免及學碩士津貼須前學年平均80分以上，博士津貼需指導教授推薦。學士最長4年、碩士2年、博士4年。','0033_s')]
FACTS['0035']['sch']=[('外國學生獎學金','學士每學年40,000元（原則6名），碩博每學年60,000元（原則7名），預算得調整，非普遍補助。','115簡章引用106年版。學士最長4年、碩士2年、博士4年，個人累計不逾5年。續領學士至少16學分、75分，研究生80分；研究生修課門檻中文2門、英文9學分存在差異待校方確認。舊生9/15–9/30申請；不得兼領教育部臺灣獎學金或本校其他獎學金。','0035_b')]
FACTS['0037'].update(b='0037_b',year='116-1',fee=1200,feeNote='2027秋季每人每系所NT$1,200或US$40，多系分別繳費，不退費。',apply='https://recruit.ntue.edu.tw/EXAM')
FACTS['0037']['sch']=[('外國籍學生獎學金','學士每人每月4,000–6,000元；研究生6,000–8,000元。','校方學生資源頁現行說明；需申請審查，不視為自動取得。115獎學金公告已找到，但完整續領成績、名額、年限與併領規則仍待確認。','0037_s2')]
FACTS['0039']['sch']=[('外國學生獎學金','新生（不含轉學生）第一年2學期免學雜費。續年分級每月6,000／4,000／2,000元，分別搭配學期間宿舍全免／全免／半免（不含寒暑假），有名額。','115簡章收錄114年12月23日公布辦法。入學時申請，在校生每年1/31、8/31前申請；操行80分。6,000級學士平均80、碩博90分；4,000級學士75、碩博85分，另有排序名額；2,000級學士70、碩博80分。學士最長4年、碩2年、博3年；第二年起每學期服務64小時，不得兼領政府或本校特別招生獎助。','0039_0')]
FACTS['0042']['sch']=[('外國學生助學金及學雜費減免','新生學雜費半免，特殊優秀者可全免（每年最多5名）；生活助學金新生每月6,000元，每年原則10個月，須申請與服務。','在校生學業前70%可半免，前5%全免（最多15名）；生活津貼依前60%／50%／30%／20%分別3,000／4,000／5,000／6,000元，服務15–30小時/月。宿舍減免須成績及操行80、前5%及服務。各項分案申請，受名額預算限制；臺灣獎學金及延修生不適用。','0042_b')]
FACTS['0044'].update(fee=1500,feeLabel='學士／碩士 NT$1,500；博士 NT$3,000',feeNote='115簡章各學制每一件申請：學士及碩士1,500元、博士3,000元；匯款手續費自付、不退費。')
FACTS['0046'].update(b='0046_b',feeNote='一般科系申請費未確認。115簡章僅「國際蒙特梭利碩士專班」明列US$100、不退費；禁止套用全校。',feeExceptions=[dict(scope='國際蒙特梭利碩士專班',amount=100,currency='USD')])
FACTS['0047']['sch']=[('外國學生獎學金','新生學士：學雜費全免／半免或宿舍全免；碩士：學雜費及學分費全免等級；博士可含住宿全免。另有教學助理補助，各項需擇優審查。','申請入學時附獎學金表及歷年成績。第二年起每學期另申請；學士成績與操行80、前50%，碩博成績85、操行80、前50%。依等級服務15–25小時；學士需華語課（有能力證明可例外），不得兼領臺灣政府獎學金。在校生官網列額度學士10,000–20,000、碩博20,000–30,000元，但總額期間表述不夠明確，不換算成年額或月額。','0047_s')]
FACTS['0048']['sch']=[('外國學生獎助學金（115學年度起入學適用）','新生第一年可申請學雜費及住宿費半額；每學期10,000元生活津貼為擇優、有名額。','114/9/24正式辦法：續領前學期排名前60%、操行80且無申誡；大二TOCFL A2，大三以上B1。前40%可申請全额；開學後依公告申請。學士最多4年（建築5年）、碩士2年。兼領費用補助及津貼服務80小時，只領其一40小時。116招生頁英文把新生津貼寫成無條件，與中文及正式辦法衝突；依正式辦法列競爭型並保留差異。','0048_p')]
FACTS['0049']['sch']=[('外國學生獎學金','每人每學期最高60,000元，名額原則不超過在校外國生及外國交換生50%，須審查，非保證。','114/6/18修正版。學士前學期至少10學分（應屆6）、在校平均70分；碩博至少1門學科、80分，無不良紀錄。開學2週內申請，每次一學期；不得兼領本校其他或外交部／教育部臺灣獎學金。一般新生第一學期資格不可直接假定。','0049_p')]
FACTS['0051']['sch']=[('外國學生獎助學金','115簡章確認設有校級外國學生獎助學金，但現行金額未能确认。','目前連結為表單入口，未能取得完整現行辦法；資格、期間、金額及續領均保留未確認，不以其他獎助或政府金額代填。','0051_b')]
FACTS['0052']['sch']=[('外國學生獎助學金－學士','一學年學雜費同額獎學金，或每月4,000元，或一學年住宿費同額獎學金；依核定，不是三項保證全領。','113/12/30版。新生隨入學申請，在校生前學年排名前50%，每次核定一年、最多4年；住宿以4人冷氣雅房為準，其他費用自付。','0052_p'),('外國學生獎助學金－研究生','菁英：一年學雜費及住宿，加博士每月5,000–10,000元／碩士2,000–6,000元（原則外國生10%）。卓越：一年學雜費及住宿（20%）。優秀：學雜費及每學期最多9學分費，或每月6,000元，或住宿，依核定。','新生隨入學申請，續領前學年80分及推薦、服務資料，每次一年，碩士最多2年、博士3年。研究生宿舍以3人冷氣雅房為準；特殊房型差價自付。','0052_p')]
FACTS['0028'].update(b='0028_web',year='115-1',fee=2000,feeNote='一般申請NT$2,000；只有SAC藝術創意研究國際碩士學位學程同時申請ICDF者可申請免繳，校方審查不符仍須補繳。',apply='https://gasys.tnua.edu.tw/IEC/ApplyForm.aspx',sch=[('外國學生獎學金','校級獎學金須完成兩學期課程後申請；現行頁未列金額，不能當作新生第一年保證補助。','以學業或課外活動優秀表現申請，未請領其他獎學金。ICDF僅限SAC碩士且有國籍等限制；臺灣獎學金需另行申請。','0028_web')])
FACTS['0048'].update(b='0048_bnew',year='116-1',feeNote='116秋季第一階段簡章及115簡章未找到明確申請費；不能視為免費。')
FACTS['0053']['sch']=[('外國碩士生獎學金','新生經審查可免學雜費及學分費；生活津貼每月6,000元，生活津貼名額原則為學院當學期新生錄取人數1/8、至少1名。','115/2/25版。入學時申請，每次一年、最長2年。續領平均及操行80分，TOCFL「B級以上」依原文，不擅自換算級別；全英語學程可依規定以一年華語課替代。每月回報；不含住宿、網路、書籍、保險。政府全額獎學金、工作居留等限制另依辦法。','0053_ms'),('外國博士生獎學金','新生經審查可免學雜費及學分費，生活津貼每月12,000元；優秀研究成果另有每月8,000元加發、每學期最多8名，不保證取得。','115/2/25版。新生须指導教授同意或於2個月內確認教授；每年續申請，最長4年。第二年平均80分及華語要求；第三、四年生活津貼續領分別需2、3篇符合規定的國際論文（第一作者，不計指導教授），每月回報，併領政府等獎助有限制。','0053_phd')]
